import base64
from pathlib import Path

FILES = {
  "app/src/main/java/com/vyba/launcher/data/repositories/WallpaperApplier.kt": "",
  "app/src/main/java/com/vyba/launcher/ui/components/AppIconTile.kt": "",
  "app/src/main/java/com/vyba/launcher/features/home/HomeScreen.kt": "",
  "app/src/main/java/com/vyba/launcher/features/themes/ThemeStudioScreen.kt": "",
  "app/src/main/java/com/vyba/launcher/features/wallpapers/WallpapersScreen.kt": "",
  "app/src/main/java/com/vyba/launcher/ui/navigation/VybaNavGraph.kt": ""
}

for rel, b64 in FILES.items():
    target = Path(rel)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(base64.b64decode(b64))

print(f"Applied VYBA Premium UI upgrade to {len(FILES)} files.")
